-- ============================================================
-- SPORTMAPS — Clubes deportivos vigentes IDRD Bogota (auto-generado)
--
-- Origen: Consulta_General_Clubes_Web.php (registro oficial IDRD)
-- Generado por scripts/scrape_idrd_clubes.py
-- Idempotente: UPSERT por external_school_imports(external_ref) UNIQUE
-- school_type='club'. Geocode coarse por centroide de localidad.
-- ============================================================

BEGIN;

-- Tabla auxiliar (ya creada por idrd_avaladas_2026.sql; defensivo)
CREATE TABLE IF NOT EXISTS public.external_school_imports (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source        text NOT NULL,
    external_ref  text NOT NULL UNIQUE,
    school_id     uuid NOT NULL REFERENCES public.schools(id) ON DELETE CASCADE,
    raw_payload   jsonb,
    imported_at   timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

